<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{{ $brand['tagline'] }}"><title>{{ $brand['name'] }}</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><style>
:root{--bg:#020b12;--panel:#061a25;--line:rgba(86,210,238,.16);--text:#effcff;--muted:#91adb7;--cyan:#43d1f0}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,sans-serif;overflow-x:hidden}a{color:inherit;text-decoration:none}.shell{width:min(1180px,calc(100% - 28px));margin:auto}.header{position:sticky;top:0;z-index:50;background:rgba(2,10,16,.86);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.nav{height:70px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;align-items:center;gap:10px;min-width:0;font-weight:850}.brand img{width:40px;height:40px;object-fit:contain;border-radius:10px}.brand i{color:var(--cyan)}.brand span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.menu{display:flex;align-items:center;gap:3px}.menu a{font-size:10px;color:#9ab4bd;padding:10px 10px;border-radius:9px;white-space:nowrap}.menu a:hover{color:#fff;background:rgba(67,209,240,.08)}.menu i{color:#63d5ed;margin-right:5px}.menu-btn{display:none;width:42px;height:42px;border:1px solid var(--line);border-radius:11px;background:#06141d;color:#e9fbff;font-size:17px}.hero{min-height:650px;display:grid;grid-template-columns:1fr 1.08fr;align-items:center;gap:35px;padding:55px 0}.hero-copy{position:relative;z-index:2}.eyebrow{display:inline-flex;gap:8px;align-items:center;color:var(--cyan);font-size:9px;letter-spacing:.2em;text-transform:uppercase}.eyebrow:before{content:"";width:22px;height:1px;background:var(--cyan);box-shadow:0 0 10px var(--cyan)}.hero h1{font-size:clamp(43px,6vw,76px);line-height:.97;letter-spacing:-.055em;margin:15px 0}.hero p{color:var(--muted);font-size:15px;line-height:1.8;max-width:600px;margin:0}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:25px}.btn{display:inline-flex;align-items:center;gap:8px;padding:12px 15px;border-radius:11px;background:linear-gradient(135deg,#37c5e6,#168faf);font-size:10px;font-weight:850}.btn.secondary{background:rgba(255,255,255,.035);border:1px solid var(--line);color:#b9d4dc}.slider{position:relative;height:430px;border:1px solid var(--line);border-radius:24px;overflow:hidden;background:linear-gradient(135deg,#092d3c,#061720);box-shadow:0 25px 70px rgba(0,0,0,.35)}.slides{height:100%;position:relative}.slide{position:absolute;inset:0;opacity:0;transform:scale(1.04);transition:opacity .8s ease,transform 5s ease;pointer-events:none}.slide.active{opacity:1;transform:scale(1);pointer-events:auto}.slide img{width:100%;height:100%;object-fit:cover}.slide:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 35%,rgba(1,8,12,.78) 100%)}.slide-copy{position:absolute;left:22px;right:22px;bottom:22px;z-index:2}.slide-copy strong{display:block;font-size:18px}.slide-copy span{display:block;color:#b0cbd2;font-size:9px;margin-top:5px}.slider-empty{height:100%;display:grid;place-items:center;color:#58cfe9}.slider-empty i{font-size:55px;filter:drop-shadow(0 0 20px rgba(67,209,240,.35))}.dots{position:absolute;z-index:5;right:18px;bottom:20px;display:flex;gap:5px}.dot{width:7px;height:7px;border:0;border-radius:50%;padding:0;background:rgba(255,255,255,.35);cursor:pointer}.dot.active{background:#fff;transform:scale(1.3)}.arrow{position:absolute;z-index:5;top:50%;transform:translateY(-50%);width:34px;height:34px;border:1px solid rgba(255,255,255,.15);border-radius:50%;background:rgba(2,11,17,.45);color:#fff;display:grid;place-items:center;cursor:pointer}.arrow.prev{left:13px}.arrow.next{right:13px}.section{padding:62px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:25px;margin-bottom:20px}.section-head h2{font-size:clamp(27px,4vw,40px);margin:7px 0 0;letter-spacing:-.035em}.section-head p{max-width:560px;color:var(--muted);font-size:11px;line-height:1.7}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:11px}.stat{padding:19px;border:1px solid var(--line);border-radius:17px;background:linear-gradient(145deg,rgba(8,38,52,.9),rgba(3,21,30,.85))}.stat i{color:var(--cyan)}.stat small{display:block;color:#6f919c;font-size:8px;text-transform:uppercase;letter-spacing:.12em;margin-top:14px}.stat strong{display:block;font-size:26px;margin-top:5px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.card{padding:19px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,rgba(8,38,52,.9),rgba(3,21,30,.85));transition:.2s}.card:hover{transform:translateY(-3px);border-color:rgba(86,210,238,.3)}.card h3{margin:0 0 8px;font-size:17px}.card p{color:var(--muted);font-size:10px;line-height:1.7;margin:0}.meta{color:#88a9b3;font-size:8px;line-height:1.8;margin-top:11px}.pill{display:inline-flex;margin-top:11px;padding:5px 8px;border-radius:999px;background:rgba(69,224,173,.08);color:#72dfbf;font-size:8px}.quick{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.quick a{display:flex;align-items:center;gap:10px;padding:15px;border:1px solid var(--line);border-radius:15px;background:rgba(7,29,40,.7);color:#a8c2ca;font-size:9px}.quick i{color:var(--cyan);font-size:16px}.footer{border-top:1px solid var(--line);padding:30px 0 50px;color:#688893;font-size:9px}@media(max-width:900px){.hero{grid-template-columns:1fr}.slider{height:380px;order:-1}.stats{grid-template-columns:repeat(2,1fr)}.cards{grid-template-columns:1fr 1fr}.quick{grid-template-columns:1fr 1fr}}@media(max-width:720px){.menu-btn{display:grid;place-items:center}.menu{display:none;position:absolute;top:70px;left:12px;right:12px;padding:8px;flex-direction:column;align-items:stretch;background:rgba(4,18,26,.98);border:1px solid var(--line);border-radius:14px}.menu.open{display:flex}.menu a{padding:12px}.hero{padding:38px 0}.section-head{display:block}.section-head p{margin-bottom:0}}@media(max-width:520px){.shell{width:calc(100% - 24px)}.brand{font-size:13px}.hero h1{font-size:43px}.hero p{font-size:13px}.slider{height:280px}.stats,.cards,.quick{grid-template-columns:1fr}.section{padding:46px 0}}
</style></head><body><header class="header"><div class="shell nav"><a class="brand" href="{{ route('home') }}">@if($brand['logo_path'])<img src="{{ asset('storage/'.$brand['logo_path']) }}" alt="{{ $brand['name'] }}">@else<i class="fa-solid fa-bolt"></i>@endif<span>{{ $brand['name'] }}</span></a><button class="menu-btn" type="button" aria-label="Open navigation"><i class="fa-solid fa-bars"></i></button><nav class="menu"><a href="{{ route('home') }}"><i class="fa-solid fa-house"></i>Home</a><a href="{{ route('site.about') }}"><i class="fa-solid fa-building"></i>About Us</a><a href="{{ route('site.plants') }}"><i class="fa-solid fa-industry"></i>Plants</a><a href="{{ route('site.future-project') }}"><i class="fa-solid fa-diagram-project"></i>Future Project</a><a href="{{ route('management') }}"><i class="fa-solid fa-people-group"></i>Management Team</a><a href="{{ route('site.career') }}"><i class="fa-solid fa-briefcase"></i>Career</a><a href="{{ route('contact') }}"><i class="fa-solid fa-envelope"></i>Contact Us</a></nav></div></header>
