<section class="section"><div class="shell"><div class="section-head"><div><span class="eyebrow">At a glance</span><h2>Built around reliable energy.</h2></div><p>{{ $brand['tagline'] }}</p></div><div class="stats"><article class="stat"><i class="fa-solid fa-industry"></i><small>Power projects</small><strong>{{ $stats['projects'] }}</strong></article><article class="stat"><i class="fa-solid fa-bolt"></i><small>Installed capacity</small><strong>{{ number_format($stats['capacity_mw'],2) }} MW</strong></article><article class="stat"><i class="fa-solid fa-circle-check"></i><small>Operational</small><strong>{{ $stats['operational'] }}</strong></article><article class="stat"><i class="fa-solid fa-leaf"></i><small>Energy focus</small><strong>Clean</strong></article></div></div></section>
