</main><footer class="footer"><div class="shell">© {{ date('Y') }} {{ $brand['name'] }} · All rights reserved.</div></footer><script>
(()=>{const btn=document.querySelector('.menu-btn'),menu=document.querySelector('.menu');btn?.addEventListener('click',()=>{menu.classList.toggle('open');btn.innerHTML=menu.classList.contains('open')?'<i class="fa-solid fa-xmark"></i>':'<i class="fa-solid fa-bars"></i>'});const slides=[...document.querySelectorAll('.slide')],dots=[...document.querySelectorAll('.dot')];if(!slides.length)return;let current=0,timer;const show=i=>{current=(i+slides.length)%slides.length;slides.forEach((s,n)=>s.classList.toggle('active',n===current));dots.forEach((d,n)=>d.classList.toggle('active',n===current))};const start=()=>{clearInterval(timer);timer=setInterval(()=>show(current+1),5000)};document.querySelector('.next')?.addEventListener('click',()=>{show(current+1);start()});document.querySelector('.prev')?.addEventListener('click',()=>{show(current-1);start()});dots.forEach(d=>d.addEventListener('click',()=>{show(Number(d.dataset.index));start()}));start()})();
</script></body></html>
